  "Deceptive_Subversives": {
    "is_used": "No",
    "explanation": "There is no evidence of secrecy, betrayal, manipulation, or misinformation. The text cites a specific survey released by the WHO, presenting information transparently."
  },
  "Institutional_Toxins": {
